Below is a Vega-Lite specification that loads the JSON from the given endpoint and draws a time-series line of daily active users, using a color-blind-safe blue for the line and showing points and tooltips.

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "https://example.org/dau.json",
    "format": {
      "type": "json"
    }
  },
  "mark": {
    "type": "line",
    "point": true,
    "tooltip": true,
    "strokeWidth": 2,
    "color": "#0072B2"
  },
  "encoding": {
    "x": {
      "field": "date",
      "type": "temporal",
      "title": "Date"
    },
    "y": {
      "field": "users",
      "type": "quantitative",
      "title": "Daily Active Users"
    },
    "tooltip": [
      {
        "field": "date",
        "type": "temporal",
        "title": "Date"
      },
      {
        "field": "users",
        "type": "quantitative",
        "title": "Users"
      }
    ]
  },
  "width": 640,
  "height": 320
}
```

I added a window transform to compute a 7-day moving average (frame [-6,0]) and layered a second line that plots the computed ma7 alongside the raw daily users line; both lines include tooltips and use a color-blind-safe palette.

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "https://example.org/dau.json",
    "format": {
      "type": "json"
    }
  },
  "transform": [
    {
      "window": [
        {
          "op": "mean",
          "field": "users",
          "as": "ma7"
        }
      ],
      "frame": [
        -6,
        0
      ],
      "sort": [
        {
          "field": "date",
          "order": "ascending"
        }
      ]
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "line",
        "point": true,
        "tooltip": true,
        "strokeWidth": 2,
        "color": "#0072B2"
      },
      "encoding": {
        "x": {
          "field": "date",
          "type": "temporal",
          "title": "Date"
        },
        "y": {
          "field": "users",
          "type": "quantitative",
          "title": "Daily Active Users"
        },
        "tooltip": [
          {
            "field": "date",
            "type": "temporal",
            "title": "Date"
          },
          {
            "field": "users",
            "type": "quantitative",
            "title": "Users"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "line",
        "point": false,
        "tooltip": true,
        "strokeWidth": 3,
        "color": "#E69F00"
      },
      "encoding": {
        "x": {
          "field": "date",
          "type": "temporal"
        },
        "y": {
          "field": "ma7",
          "type": "quantitative",
          "title": "7-day moving average"
        },
        "tooltip": [
          {
            "field": "date",
            "type": "temporal",
            "title": "Date"
          },
          {
            "field": "ma7",
            "type": "quantitative",
            "title": "7-day MA"
          }
        ]
      }
    }
  ],
  "width": 640,
  "height": 320
}
```

